stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_variable_domain",
      "evidence": "Demand of Each Retail Store (in units) ... Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "NonNegativeIntegers"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "transport goods to meet all nine retail stores' demands",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] = demand[j]"
      ],
      "plausibility": [
        0.55,
        0.45
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_linking_form",
      "evidence": "Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= demand[j]*y[i]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "Opening Costs for Each Distribution Center (in dollars) ... Transportation Cost Per Unit ... (in dollars)",
      "options": [
        "report total cost in dollars (opening + transport)",
        "report total cost in thousands of dollars"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "report total cost in dollars (opening + transport)"
    },
    {
      "decision": "opening_variable_domain",
      "evidence": "deciding how best to structure its distribution network ... opening the right combination of distribution centers",
      "options": [
        "Binary y[i]",
        "NonNegativeReals y[i] in [0,1]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "Binary y[i]"
    },
    {
      "decision": "transport_cost_orientation",
      "evidence": "Transportation Cost Per Unit from Each Distribution Center to Retail Stores",
      "options": [
        "trans_cost[i][j] with i=center row, j=store column",
        "trans_cost[j][i] with j=store row, i=center column"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "trans_cost[i][j] with i=center row, j=store column"
    }
  ]
